"""Layer 15 MLP hidden unit 578 (the component's activation is this unit, times a fixed
scale), read as a "definite subject noun phrase" detector.

The activation is mostly negative where a definite noun phrase is being read and its verb
is coming:

  * the head noun of "the N" (or "the ADJ N") is pushed negative: more so when the phrase
    opens a clause ("The method ..."), and much more when N was already mentioned earlier in
    the document (a known referent);
  * the auxiliary right after "the N" ("The method is ...") is pushed strongly negative;
  * an auxiliary after some other noun is mildly negative;
  * an auxiliary after a pronoun or "this"/"that" ("it is", "this is") is mildly positive.

Everything else is predicted as 0. Word classes come from WordNet (nouns) and small closed
lists (articles, auxiliaries, pronouns). The values are rounded group means fit on training
text. The program ignores token identity beyond these classes, which is why it explains only
a small share of the variance.
"""

import wordnet

READS = ()

AUX = {
    "is", "was", "are", "were", "be", "has", "have", "had", "can", "will", "would",
    "should", "may", "might", "must", "could", "does", "do", "did",
}
DEMONSTRATIVE = {"this", "that", "these", "those"}
POSSESSIVE = {"your", "our", "their", "my", "his", "her", "its"}
PRONOUN = {"it", "he", "she", "they", "we", "you", "i", "which", "this", "that"}
CLAUSE_START = {".", ",", "that", "if", "when", "because", "but", "and", "so", "while"}


def word(token):
    return token.strip().lower()


def is_noun(w):
    return w.isalpha() and w not in AUX and "noun" in wordnet.parts_of_speech(w)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    # carry: (document label, words already seen in this document)
    if carry is None or carry[0] != doc:
        carry = (doc, set())
    seen = carry[1]
    toks = prefix.token_strings
    docs = prefix.document_ids

    def back(k):
        # the word k tokens back, within the same document; "" before it
        if len(toks) > k and docs[-1 - k] == doc:
            return word(toks[-1 - k])
        return ""

    cur, prev, before = word(toks[-1]), back(1), back(2)
    repeated = cur in seen
    seen.add(cur)
    prev_is_the_noun = is_noun(prev) and before == "the"
    if cur in AUX:
        if prev in PRONOUN:
            value = 0.27
        elif prev_is_the_noun:
            value = -2.9
        elif is_noun(prev):
            value = -0.3
        else:
            value = -0.06
    elif is_noun(cur) and prev == "the":
        value = -0.75 - 0.9 * repeated - 0.4 * (before in CLAUSE_START)
    elif is_noun(cur) and before == "the" and prev.isalpha():
        value = -0.3
    elif is_noun(cur) and prev in DEMONSTRATIVE:
        value = 0.05
    elif is_noun(cur) and prev in POSSESSIVE:
        value = -0.29
    elif cur == "," and prev_is_the_noun:
        value = -0.74
    else:
        value = 0.0
    return (doc, seen), float(value)

"""Layer 15 MLP down_proj, component 595: a weak, mostly token-level signal.

The component reads its input almost entirely through MLP hidden unit 595 of layer 15
(that unit carries about 0.73 of its input direction's norm), so its activation tracks how
hard that unit fires. The activation is noisy: most of its variance is rare large swings
that depend on context, which no rule over the current token captures.

This program keeps only the part a few word classes explain:
- negative on Chinese grammar particles (的 了 之 地 着 者 性 得), its most consistent negatives;
- negative on English word endings split off as their own tokens ("ing", "ly", "ed",
  "able", "ers", ...) and on Russian word endings (-ся, -ный, -ная, -ых, ...);
- slightly negative on the prepositions " by", " which", " whom", " of";
- positive on function words such as " or", " that", " what", " would", " than", " both".

Every other token predicts 0. Predictions use only the current token, so they are causal.
"""

import regex

READS = ()

PARTICLES = set("的了之地着者性得")
ENDINGS = {"ing", "ly", "ed", "able", "ably", "ers", "er", "en", "es", "s", "al", "bed"}
NEG_WORDS = {" by", " which", " whom", " of"}
POS_WORDS = {" or", " that", " what", " would", " will", " than", " both", " me"}
CYRILLIC_ENDING = regex.compile(r"\p{Cyrillic}+(ся|ный|ная|ные|ных|ным|ном|ых|ые|ый|ля|итель|атель)")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s in PARTICLES:
        value = -0.6
    elif s in ENDINGS or CYRILLIC_ENDING.fullmatch(s):
        value = -0.3
    elif s in NEG_WORDS:
        value = -0.1
    elif s in POS_WORDS:
        value = 0.2
    else:
        value = 0.0
    return carry, value

READS = ()

# The suffix "s" that marks a possessive or plural on a noun (Sultan's, CNN's, orphs).
# After a pronoun it is a contraction (it's, let's, here's) and stays quiet.
POSSESSIVE_S = {"s", "'s", "’s"}
PRONOUNS = {"it", "that", "here", "let", "what", "there", "he", "she", "who", "this", "where", "how", "one"}
# Other grammatical endings and particles that attach to a stem.
GENITIVE_PARTICLES = {"的", "の", "了"}  # Chinese 的, Japanese の, 了
CYRILLIC_ENDINGS = {"ы", "и", "е", "ов", "ах", "ами", "ми", "а", "та"}
ENGLISH_SUFFIXES = {"ing", "ed", "ly", "en", "ness", "ity", "ler", "lar", "th", "ng"}
PLURAL_ES = {"es"}


def step(carry, prefix, upstream):
    """Activation of a suffix token that completes a noun-like stem; 0 elsewhere."""
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if token in POSSESSIVE_S:
        return carry, 0.4 if previous in PRONOUNS else 5.5
    if token in GENITIVE_PARTICLES:
        return carry, 3.8
    if token in CYRILLIC_ENDINGS:
        return carry, 2.9
    if token in PLURAL_ES or token in ENGLISH_SUFFIXES:
        return carry, 2.2
    return carry, 0.0

"""Layer 15 MLP hidden unit 619 (component 619 of layers.15.mlp.down_proj).

The component reads almost only that hidden unit (its read vector is 0.93 on it),
so its activation is that unit's value times about 1.08. Its write direction
promotes agentive "person / -er" tokens (者, holder, owner) when the activation
is positive.

This program predicts each token's activation as the mean activation of the
token's script class, measured on 1.5M training tokens. It is a weak predictor:
the activation is dense and heavy-tailed (std 0.51), and script explains well under
1% of its variance.
"""

READS = ()

MEAN_BY_SCRIPT = {
    "han": 0.075, "kana": 0.021, "hangul": -0.069, "cyrillic": 0.018,
    "greek": 0.081, "arabic": 0.079, "latin": -0.026, "digit": 0.03,
    "space": 0.029, "punct": -0.011, "partial": -0.025, "other": 0.088,
}


def script(s):
    if not s:
        return "other"
    if "�" in s:
        return "partial"
    c = s.strip()
    if not c:
        return "space"
    ch = c[0]
    if "一" <= ch <= "鿿" or "㐀" <= ch <= "䶿":
        return "han"
    if "぀" <= ch <= "ヿ":
        return "kana"
    if "가" <= ch <= "힯":
        return "hangul"
    if "Ѐ" <= ch <= "ӿ":
        return "cyrillic"
    if "؀" <= ch <= "ۿ":
        return "arabic"
    if "Ͱ" <= ch <= "Ͽ":
        return "greek"
    if ch.isdigit():
        return "digit"
    if ch.isascii() and ch.isalpha():
        return "latin"
    if ch.isalpha():
        return "other"
    return "punct"


def step(carry, prefix, upstream):
    return carry, MEAN_BY_SCRIPT[script(prefix.token_strings[prefix.position])]

"""Layer 15 MLP hidden unit 624, as component down_proj:624. Its input direction is mostly
that one neuron (about 80% of its norm), so its activation is that neuron's value scaled by
about 1.1; its output is the neuron's write into the residual stream.

Plain-language summary: the activation is near zero and slightly negative on most tokens,
with rare large positive spikes (and a few negative ones). The clearest spikes are:

  * a NUL byte (`\\x00`), which appears when UTF-16 text is read as bytes: large;
  * a character that betrays mis-decoded or OCR-damaged text (mojibake `Ã`, long s `ſ`,
    Arabic shadda `ّ`, euro sign `€`): large, but rare;
  * a soft hyphen (U+00AD) or a combining mark: very large, very rare;
  * a fragment of a multi-byte character cut in two (decodes to U+FFFD): slightly positive;
  * a hyphen right after a letter, splitting a word (e.g. "approvi-", "Treat-"): positive on
    average, sometimes large;
  * every other token: a small baseline just below zero.

This program predicts those levels. It explains only a small share of the variance. Most of
the large spikes sit on ordinary tokens, mostly newlines and fragments inside a word or
phrase, where no simple property of the token or the token before it separates a spike from
the baseline, so the program predicts the baseline there.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

BASELINE = -0.06  # typical activation on ordinary tokens
NUL_BYTE = 7.4  # a NUL byte (UTF-16 text read as bytes)
SOFT_HYPHEN = 17.6  # soft hyphen or combining mark (very rare)
GARBLED_CHAR = 4.8  # Ã, ſ, ّ, € : signs of mis-decoded or OCR-damaged text
PARTIAL_CHAR = 0.26  # a fragment of a multi-byte character (decodes to U+FFFD)
WORD_HYPHEN = 1.0  # a hyphen right after a letter, splitting a word

GARBLED_CHARS = frozenset("Ãſّ€")


def _ends_in_letter(text: str) -> bool:
    text = text.strip()
    return bool(text) and text[-1].isalpha()


def step(carry, prefix, upstream: Mapping):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""

    if cur == "\x00":
        value = NUL_BYTE
    elif "­" in cur or "̀" <= cur[-1:] <= "ͯ":
        value = SOFT_HYPHEN
    elif cur and cur in GARBLED_CHARS:
        value = GARBLED_CHAR
    elif "�" in cur:
        value = PARTIAL_CHAR
    elif cur.strip() == "-" and _ends_in_letter(prev):
        value = WORD_HYPHEN
    else:
        value = BASELINE
    return carry, float(value)

"""Coordinator detector for component layers.15.mlp.down_proj:638.

What it does: it fires on the word that joins two parallel items, a conjunction such as
"and" or "or" (and its translations: und, et, и, ou, y, e, och, và), or a list mark such as
a comma, 、 ，, a slash or an opening bracket. It fires most strongly when the joiner follows
an adjective or a verb, as in "smooth [and] efficient", "angular [or] circular",
"easy [and] ...", where the next word is expected to be another adjective or verb of the
same kind. A joiner after a noun ("products [and] services") fires weakly, and after a
plural noun it is slightly negative. Contrast words ("nor", "but", "than", "rather",
"vs") get a small value, and everything else is predicted as 0.

Why: the component's largest activations sit on such joiners, and the part of speech of
the word before the joiner (from WordNet) is what separates strong cases from weak ones.
"""

import re

import wordnet

READS = ()

JOINERS = {" and", " or", " &", " und", " et", " e", " y", " и", " ou", " och", " và"}
CONTRASTS = {" nor", " but", " yet", " than", " rather", " vs", " versus"}
LIST_MARKS = {",", "，", "、", "/"}

# predicted activation for a joiner, by the kind of word before it
JOINER_LEVEL = {"adj_or_verb": 3.5, "other": 0.8, "noun": 0.4, "plural_noun": -0.5}
# predicted activation for a list mark, by the kind of word before it
LIST_LEVEL = {"adj_or_verb": 0.8, "other": 0.3, "noun": 0.15, "plural_noun": 0.0}
BRACKET_LEVEL = 0.4
CONTRAST_LEVEL = 0.5


def previous_word_kind(prefix):
    """'adj_or_verb', 'plural_noun', 'noun' or 'other', from WordNet, for the word just
    before the token being predicted (a word from the same document only)."""
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return "other"
    match = re.search(r"([A-Za-z]+)$", prefix.text_prefixes[-2])
    if match is None:
        return "other"
    word = match.group(1).lower()
    senses = wordnet.parts_of_speech(word)
    if not senses:
        return "other"
    if "noun" not in senses and ("adjective" in senses or "verb" in senses):
        return "adj_or_verb"
    if senses == {"noun"}:
        return "plural_noun" if word.endswith("s") and not word.endswith("ss") else "noun"
    return "other"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in JOINERS:
        return carry, JOINER_LEVEL[previous_word_kind(prefix)]
    if token in LIST_MARKS:
        return carry, LIST_LEVEL[previous_word_kind(prefix)]
    if token == " (":
        return carry, BRACKET_LEVEL
    if token in CONTRASTS:
        return carry, CONTRAST_LEVEL
    return carry, 0.0

"""Layer 15 MLP hidden unit 639 (the component's input weight is 0.80 on this unit, and
its output weight is the component's output direction), read as a word-class rule.

The unit is quiet on most words and, when it moves, is usually negative on function words
that open or join a noun phrase: determiners and quantifiers ("the", "all", "those",
"each"), prepositions ("of", "in", "to", "by") and relative pronouns ("who", "that",
"which"). Inside fixed formulaic phrases ("as of", "as defined", "set forth", "all who",
"the date", "the person") it is more strongly negative. Other words get a small
negative baseline, since the unit is slightly negative on average.

This rule uses only the current word and the word before it, in the same document. It
explains very little: about 0.3% of the variance on eval. Its predictions barely change
the model's output. The rest of the variance depends on wider context, which a table of
word pairs (about 5% on held-out rows) does not capture.
"""

READS = ()

DETERMINERS = {
    "the", "those", "all", "both", "each", "any", "such", "their", "its", "these",
    "this", "every",
}
PREPOSITIONS = {
    "of", "in", "to", "at", "by", "for", "from", "on", "between", "within", "during",
    "than", "over", "after", "with", "into", "through", "under", "about",
}
RELATIVES = {"who", "that", "which", "whom", "whose"}

# (previous word, current word) -> typical activation in fixed phrases
FORMULAS = {
    ("as", "of"): -2.6, ("as", "defined"): -4.0, ("as", "specified"): -3.0,
    ("as", "indicated"): -1.3, ("as", "provided"): -1.2, ("as", "set"): -1.4,
    ("set", "forth"): -1.9, ("those", "who"): -1.0, ("all", "who"): -3.1,
    ("anyone", "who"): -1.5, ("everyone", "who"): -1.5, ("for", "those"): -1.1,
    ("than", "those"): -1.3, ("the", "date"): -1.9, ("the", "person"): -1.4,
    ("the", "people"): -0.9, ("minds", "of"): -3.4, ("lives", "of"): -2.2,
    ("needs", "of"): -1.5, ("specified", "in"): -1.3,
}

BASELINE = -0.02  # the component is slightly negative on average
CLASS_VALUE = {"det": -0.10, "prep": -0.05, "rel": -0.07}


def word_class(word):
    if word in DETERMINERS:
        return CLASS_VALUE["det"]
    if word in PREPOSITIONS:
        return CLASS_VALUE["prep"]
    if word in RELATIVES:
        return CLASS_VALUE["rel"]
    return BASELINE


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    if (before, word) in FORMULAS:
        return carry, FORMULAS[(before, word)]
    return carry, word_class(word)
